export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors(url) });
    if (url.pathname === '/api/claude' && request.method === 'POST') return apiClaude(request, url, env || {});
    if (url.pathname === '/api/lens' && request.method === 'POST') return apiLens(request, url, env || {});
    if (request.method !== 'GET') return json({ error: 'GET only' }, url, 0, 405);
    if (url.pathname === '/' || url.pathname === '/index.html') {
      return new Response(INDEX_HTML, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache', 'x-robots-tag': 'noindex' } });
    }
    if (url.pathname === '/api/sites') return json(siteStatus(env), url, 0);
    if (url.pathname === '/api/search') return apiSearch(url, env || {}, ctx);
    if (url.pathname === '/api/img') return apiImage(url);
    if (url.pathname === '/api/probe') return apiProbe(url);
    if (url.pathname === '/api/price') return apiPrice(url, env);
    if (url.pathname === '/api/discover') return apiDiscover(url, env || {});
    if (url.pathname.startsWith('/api/photo/')) return apiPhoto(url, env || {});
    return new Response('Not found', { status: 404 });
  },
};

// ---------- API ----------

function cors(url) {
  return { 'access-control-allow-origin': url.origin, 'access-control-allow-methods': 'GET, POST, OPTIONS', 'access-control-allow-headers': 'content-type', vary: 'Origin' };
}

function json(body, url, maxAge, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': maxAge ? `public, max-age=${maxAge}` : 'no-store', ...cors(url) },
  });
}

function disabledSet(env) {
  return new Set(String((env && env.DISABLED_SITES) || '').split(',').map(s => s.trim()).filter(Boolean));
}

function siteStatus(env) {
  env = env || {};
  const off = disabledSet(env), sites = {};
  for (const [id, s] of Object.entries(SITES)) {
    const enabled = !!s.search && s.enabled && !off.has(id);
    sites[id] = { name: s.name, enabled, working: health[id] ? health[id].ok : null };
    if (!enabled) sites[id].note = s.reason || 'Switched off';
    else if (health[id] && !health[id].ok) sites[id].note = health[id].error;
  }
  sites.ebay.mode = env.EBAY_CLIENT_ID && env.EBAY_CLIENT_SECRET ? 'api' : 'html';
  if (!env.SERPER_API_KEY) for (const id of Object.keys(SITES).filter(k => k === 'google' || SITES[k].google)) Object.assign(sites[id], { enabled: false, note: 'Add a SERPER_API_KEY secret to search this through Google.' });
  const claude = { on: !!env.ANTHROPIC_API_KEY, limit: claudeLimit(env) };
  const lens = { on: !!(env.SERPAPI_KEY && env.PHOTOS), missing: [env.SERPAPI_KEY ? '' : 'SERPAPI_KEY secret', env.PHOTOS ? '' : 'PHOTOS storage'].filter(Boolean) };
  return { sites, cacheSeconds: CACHE_SECONDS, claude, lens, discover: !!env.SERPER_API_KEY, version: APP_VERSION, built: BUILT_AT };
}

// ---------- Claude check (optional, paid): only runs once an ANTHROPIC_API_KEY secret is added ----------
// The browser sends a shortlist (up to 20 listings, each with a small photo). Claude says which
// category each one is, how well it matches what you want, and how rare it is. The key never leaves the Worker.
const CLAUDE_BATCH = 20, claudeUse = new Map();
const claudeLimit = env => Math.max(0, parseInt(env.CLAUDE_DAILY_LIMIT || '300', 10) || 0); // calls per visitor per day
const shortText = (v, n) => String(v == null ? '' : v).replace(/[\u0000-\u001f]+/g, ' ').trim().slice(0, n);
const jpeg = v => typeof v === 'string' && /^[A-Za-z0-9+/=]+$/.test(v) && v.length < 60000 ? v : '';

async function apiClaude(request, url, env) {
  const fail = (error, status = 200) => json({ verdicts: [], error }, url, 0, status);
  if (!env.ANTHROPIC_API_KEY) return fail('The Claude check is off. Add an ANTHROPIC_API_KEY secret to the Worker to turn it on.', 403);
  const origin = request.headers.get('origin');
  if (origin && origin !== url.origin) return fail('Not allowed from another site', 403);
  const text = await request.text();
  if (text.length > 700000) return fail('Too much at once', 413);
  let body;
  try { body = JSON.parse(text); } catch (e) { return fail('Bad request', 400); }
  // Daily cap per visitor. It is kept in this Worker's memory, so it is approximate: set a monthly
  // spend limit in the Anthropic Console as well, which is the real ceiling.
  const day = new Date().toISOString().slice(0, 10), who = day + ':' + (request.headers.get('cf-connecting-ip') || 'anon');
  const used = claudeUse.get(who) || 0, limit = claudeLimit(env);
  if (used >= limit) return fail(`Daily limit of ${limit} Claude checks reached. It resets at midnight UTC.`, 429);
  for (const k of claudeUse.keys()) if (!k.startsWith(day)) claudeUse.delete(k);
  const MODES = { brand: claudeBrand, filter: claudeTitles, translate: claudeTranslate, photo: claudePhoto, shops: claudeShops, models: claudeModels };
  if (MODES[body.mode]) {
    claudeUse.set(who, used + 1);
    const r = await MODES[body.mode](body, env);
    return r.error ? fail(r.error) : json({ ...r, left: limit - used - 1 }, url, 0);
  }

  const want = body.want || {}, cats = (Array.isArray(body.categories) ? body.categories : []).slice(0, 30)
    .map(c => ({ id: shortText(c && c.id, 24).replace(/[^a-z0-9_-]/gi, ''), label: shortText(c && c.label, 40) })).filter(c => c.id);
  const items = (Array.isArray(body.items) ? body.items : []).slice(0, CLAUDE_BATCH)
    .map(i => ({ k: shortText(i && i.k, 80), title: shortText(i && i.title, 200), price: shortText(i && i.price, 30), site: shortText(i && i.site, 40), img: jpeg(i && i.img) })).filter(i => i.k);
  if (!items.length) return fail('Nothing to check', 400);
  const photo = jpeg(want.photo);
  const lines = [
    `The shopper wants: ${shortText(want.text, 200) || '(no description)'}`,
    want.colour ? `Colour: ${shortText(want.colour, 30)}. Other colours do not match.` : 'Any colour is fine.',
    want.categories && want.categories.length ? `Categories they picked: ${want.categories.map(c => shortText(c, 30)).join(', ')}.` : 'They did not pick a category.',
    photo ? 'Their photo of the exact item comes first. "match" means: is this listing the same item (same model or design) as in their photo?' : '"match" means: how well this listing fits what they described.',
    'Category ids you can use: ' + cats.map(c => `${c.id} (${c.label})`).join(', ') + ', other (not the item itself, e.g. a poster, box, tag, sticker or a different kind of product).',
  ];
  const content = [{ type: 'text', text: lines.join('\n') }];
  if (photo) content.push({ type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: photo } });
  for (const i of items) {
    content.push({ type: 'text', text: `Listing ${i.k}: ${i.title} | ${i.price} | ${i.site}` });
    if (i.img) content.push({ type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: i.img } });
  }
  const tool = {
    name: 'grade', description: 'Record a verdict for every listing.',
    input_schema: { type: 'object', required: ['items'], properties: { items: { type: 'array', items: { type: 'object', required: ['k', 'category', 'match', 'rarity', 'why'], properties: {
      k: { type: 'string', description: 'The listing id, exactly as given' },
      category: { type: 'string', enum: [...cats.map(c => c.id), 'other'] },
      match: { type: 'number', description: '0 to 1' },
      rarity: { type: 'integer', description: '1 common, 2 uncommon, 3 rare, 4 very rare, 5 grail: how hard this exact piece is to find second-hand' },
      why: { type: 'string', description: 'At most 12 words' },
    } } } } },
  };
  claudeUse.set(who, used + 1);
  const { call, out, error } = await askClaude(env, 'You check second-hand and new clothing listings for a shopper, using each title and photo. Judge rarity on brand, line, era, collaboration and condition, and say 1 when unsure. Be strict about category and match: a listing that only mentions the item, or shows something else, gets a low match. Give a verdict for every listing.', content, tool, 2000, photo ? 1 : 0);
  if (error) return fail(error);
  const ids = new Set(items.map(i => i.k)), catIds = new Set([...cats.map(c => c.id), 'other']);
  const verdicts = ((call && call.input && call.input.items) || []).filter(v => v && ids.has(v.k)).map(v => ({
    k: v.k, category: catIds.has(v.category) ? v.category : '', match: Math.max(0, Math.min(1, +v.match || 0)),
    rarity: Math.max(1, Math.min(5, Math.round(+v.rarity) || 1)), why: shortText(v.why, 120),
  }));
  return json({ verdicts, left: limit - used - 1, usage: out.usage || null }, url, 0);
}

// Prompt caching: everything up to the block marked cacheAt (tools, system, the shopper's request and photo) is the same
// for every batch of one search, so later batches read it at a tenth of the price. Below Claude's minimum (512 tokens
// on Haiku 5.5) nothing is cached and nothing extra is charged.
// Most calls use the quick model (CLAUDE_MODEL, Haiku). Reading what a search means is one call per search,
// so it uses a stronger one (CLAUDE_BRAND_MODEL, Sonnet), and falls back to the quick model if that one is refused.
const QUICK_MODEL = env => env.CLAUDE_MODEL || 'claude-haiku-5-5';
const STRONG_MODEL = env => env.CLAUDE_BRAND_MODEL || 'claude-sonnet-5-5';
async function askClaude(env, system, content, tool, maxTokens, cacheAt = -1, model = '') {
  if (cacheAt >= 0 && content[cacheAt]) content[cacheAt] = { ...content[cacheAt], cache_control: { type: 'ephemeral' } };
  const first = await askClaudeOnce(env, system, content, tool, maxTokens, model || QUICK_MODEL(env));
  if (first.error && model && model !== QUICK_MODEL(env) && first.status !== 401) return askClaudeOnce(env, system, content, tool, maxTokens, QUICK_MODEL(env));
  return first;
}
async function askClaudeOnce(env, system, content, tool, maxTokens, model) {
  let res;
  try {
    res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({ model, max_tokens: maxTokens, tools: [tool], tool_choice: { type: 'tool', name: tool.name }, system: [{ type: 'text', text: system }], messages: [{ role: 'user', content }] }),
    });
  } catch (e) { return { error: 'Could not reach Claude' }; }
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    return { status: res.status, error: res.status === 401 ? 'The ANTHROPIC_API_KEY secret was not accepted.' : `Claude said: ${shortText(err.error && err.error.message, 160) || 'error ' + res.status}` };
  }
  const out = await res.json().catch(() => ({}));
  return { out, call: (out.content || []).find(b => b.type === 'tool_use') };
}
const strList = (v, n, len = 60) => (Array.isArray(v) ? v : []).map(x => shortText(x, len)).filter(Boolean).slice(0, n);

// What is this brand or line? Which brands sit above it, who it is with, and how people misspell it.
async function claudeBrand(body, env) {
  const q = shortText(body.query, 100);
  const catIds = (Array.isArray(body.categories) ? body.categories : []).map(c => shortText(c, 24).replace(/[^a-z0-9_-]/gi, '')).filter(Boolean).slice(0, 30);
  if (!catIds.length) catIds.push('other');
  if (!q) return { error: 'Nothing to look up' };
  const str = d => ({ type: 'string', description: d }), arr = d => ({ type: 'array', items: { type: 'string' }, description: d });
  const tool = { name: 'brand', description: 'Describe where this search sits in fashion brand hierarchies.', input_schema: { type: 'object', required: ['kind', 'brand', 'line', 'about', 'misspellings'], properties: {
    kind: { type: 'string', enum: ['brand', 'line', 'collaboration', 'model', 'none'], description: 'brand: the search is a whole brand, maybe with a garment type. line: it names a diffusion line or sub-label. collaboration: a collab. model: a brand plus a product or style name (most searches for one specific item). none: not a fashion brand.' },
    brand: str('The brand or label\'s full name, written the way the brand writes it, even when the search abbreviates it (e.g. "Dries Van Noten" for "DVN", "Comme des Garcons" for "CDG", "Scarlett & Sam" for "scarlett and sam"). The brand is usually the first words of the search'),
    brand_names: arr('Other names for the top brand: abbreviations sellers use (DVN, CDG), Japanese katakana, Chinese, short forms'),
    related_models: arr('Product or style names this brand uses for items that fit the search, when the search describes a feature rather than naming one (e.g. for "Prada nylon shoulder bag": Re-Edition). Only names you are sure of; usually empty'),
    line: str('For a collaboration, its usual name, e.g. "Kiko Kostadinov x Stussy". Otherwise only a real diffusion line or sub-label sold under its own name (e.g. Issey Sport, Shadow Project, Comme des Garcons Homme). Never a product or style name, never the brand itself, and only if the search itself names that line. Empty for most searches'),
    line_names: arr('Other names for that line or collaboration: full name with the brand, short forms, and Japanese katakana (e.g. キココスタディノフ ステューシー)'),
    parents: arr('Only when line is set: the brands above that line. Otherwise empty'),
    collaborators: arr('Designers or brands it is a collaboration with, with Japanese katakana where common'),
    sub_lines: arr('If the search is a whole brand: its main lines, up to 5'),
    model: str('The product or style name in the search, without the brand and without the garment type: "Pintuck" for "Deiji Studios pintuck jacket", "Cocoon" for "scarlett and sam cocoon padded jacket", "Gigi Utility" for "Assembly Label gigi utility pants". If the search describes a feature instead, that feature as sellers write it: "Back Zip" for "dvn backzip". Empty if the search names neither'),
    categories: { type: 'array', items: { type: 'string', enum: catIds }, description: 'Which of these categories the search is about, only if it names one or names a single product of one category. Empty when it describes a feature several kinds of garment share (e.g. "back zip" can be a jacket or a sweater)' },
    colour: str('A colour the search asks for, else empty'),
    eras: { type: 'array', items: { type: 'string', enum: ['70s', '80s', '90s', '00s', 'Y2K'] }, description: 'Eras the search asks for, else empty' },
    price_max: { type: 'number', description: 'Highest price in Australian dollars if the search states one, else 0' },
    model_names: arr('Other spellings sellers use for that product name or feature (e.g. "Pin Tuck", "Backzip", "Back-Zip"), especially Japanese katakana (e.g. バックジップ)'),
    misspellings: arr('Up to 8 misspellings of the BRAND name that sellers really use, lower case'),
    about: str('One short sentence: what it is. Only facts you are sure of (no guessed city or history); leave empty if unsure'),
  } } };
  const { call, error } = await askClaude(env, 'You are an expert on fashion brands, including small independent labels, their diffusion lines, sub-labels and collaborations, and how resale listings in Japan and the West name them. Split the search into brand, product name and garment type. Product names (Pintuck, Cocoon, Gigi) are models, not lines. Only state what you are confident of; leave fields empty when unsure.',
    [{ type: 'text', text: `Search: ${q}` }], tool, 900, -1, STRONG_MODEL(env));
  if (error) return { error };
  const i = (call && call.input) || {};
  return { family: {
    kind: ['brand', 'line', 'collaboration', 'model', 'none'].includes(i.kind) ? i.kind : 'none', brand: shortText(i.brand, 60), brand_names: strList(i.brand_names, 6),
    line: shortText(i.line, 60), line_names: strList(i.line_names, 6), parents: strList(i.parents, 4), collaborators: strList(i.collaborators, 6),
    sub_lines: strList(i.sub_lines, 5), model: shortText(i.model, 60),
    categories: strList(i.categories, 4).filter(c => catIds.includes(c)), colour: /[a-z]/i.test(String(i.colour || '')) ? shortText(String(i.colour).replace(/["'“”]/g, ''), 30) : '', eras: strList(i.eras, 4).filter(e => ['70s', '80s', '90s', '00s', 'Y2K'].includes(e)),
    price_max: Math.max(0, Math.min(1e6, +i.price_max || 0)), model_names: strList(i.model_names, 6), related_models: strList(i.related_models, 6), misspellings: strList(i.misspellings, 8).map(x => x.toLowerCase()), about: shortText(i.about, 160),
  } };
}

// Titles from the wider searches (e.g. all of Stone Island): which are really the thing the shopper asked for?
async function claudeTitles(body, env) {
  const want = body.want || {};
  const items = (Array.isArray(body.items) ? body.items : []).slice(0, 80).map(i => ({ k: shortText(i && i.k, 80), title: shortText(i && i.title, 160), price: shortText(i && i.price, 30) })).filter(i => i.k && i.title);
  if (!items.length) return { error: 'Nothing to check' };
  const lines = [
    `The shopper searched for: ${shortText(want.text, 200)}`,
    want.line ? `They want ${shortText(want.line, 60)} specifically${want.about ? ' (' + shortText(want.about, 160) + ')' : ''}. Names it goes by: ${strList(want.names, 8).join(', ')}.` : '',
    strList(want.keywords, 3).length ? `It must be: ${strList(want.keywords, 3).join(', ')}.` : '',
    strList(want.categories, 12).length ? `Categories: ${strList(want.categories, 12).join(', ')}.` : '',
    'These listings came from wider searches and do not clearly name it. For each, answer yes (the title shows it is what they want, e.g. a known model, collection, collaborator name or season of that line), no (it is the main brand, another line or another item), or maybe (cannot tell from the title).',
  ].filter(Boolean);
  const listed = items.map(i => `${i.k}: ${i.title}${i.price ? ' | ' + i.price : ''}`).join('\n');
  const tool = { name: 'sort', description: 'Record a verdict for every listing.', input_schema: { type: 'object', required: ['items'], properties: { items: { type: 'array', items: { type: 'object', required: ['k', 'm'], properties: {
    k: { type: 'string' }, m: { type: 'string', enum: ['yes', 'no', 'maybe'] }, why: { type: 'string', description: 'At most 8 words, only for yes or maybe' },
  } } } } } };
  const { call, out, error } = await askClaude(env, 'You sort resale listings by their titles, which may be in Japanese or English. Say no unless the title gives real evidence. Give a verdict for every listing.', [{ type: 'text', text: lines.join('\n') }, { type: 'text', text: listed }], tool, 3000, 0);
  if (error) return { error };
  const ids = new Set(items.map(i => i.k));
  return { usage: (out && out.usage) || null, verdicts: ((call && call.input && call.input.items) || []).filter(v => v && ids.has(v.k) && ['yes', 'no', 'maybe'].includes(v.m)).map(v => ({ k: v.k, m: v.m, why: shortText(v.why, 80) })) };
}

// Listing titles in another language, for display only.
const LANG_NAMES = { en: 'English', ja: 'Japanese', zh: 'Simplified Chinese', ko: 'Korean', fr: 'French', es: 'Spanish', de: 'German', it: 'Italian', pt: 'Portuguese' };
async function claudeTranslate(body, env) {
  const to = LANG_NAMES[body.to];
  if (!to) return { error: 'Unknown language' };
  const items = (Array.isArray(body.items) ? body.items : []).slice(0, 60).map(i => ({ k: shortText(i && i.k, 12), t: shortText(i && i.t, 200) })).filter(i => i.k && i.t);
  if (!items.length) return { error: 'Nothing to translate' };
  const tool = { name: 'translations', description: 'Record a translation for every title.', input_schema: { type: 'object', required: ['items'], properties: { items: { type: 'array', items: { type: 'object', required: ['k', 't'], properties: { k: { type: 'string' }, t: { type: 'string' } } } } } } };
  const { call, error } = await askClaude(env, `You translate second-hand fashion listing titles into natural ${to}, the way a shop would write them. Keep brand, line and model names in their usual ${to} or English spelling, and keep sizes, measurements and model numbers as they are. Translate every title.`,
    [{ type: 'text', text: items.map(i => `${i.k}: ${i.t}`).join('\n') }], tool, 3000);
  if (error) return { error };
  const ids = new Set(items.map(i => i.k));
  return { items: ((call && call.input && call.input.items) || []).filter(v => v && ids.has(v.k) && typeof v.t === 'string').map(v => ({ k: v.k, t: shortText(v.t, 240) })) };
}

// The earlier price, only when it is really higher than the price now (at least 3% off).
function wasPrice(was, price) {
  return was && price && was > price * 1.03 ? Math.round(was * 100) / 100 : undefined;
}

// What is in the shopper's photo? Brand, model, category and the words to search with.
async function claudePhoto(body, env) {
  const photo = jpeg(body.photo);
  if (!photo) return { error: 'No photo' };
  const cats = (Array.isArray(body.categories) ? body.categories : []).map(c => shortText(c, 24).replace(/[^a-z0-9_-]/gi, '')).filter(Boolean).slice(0, 30);
  const str = d => ({ type: 'string', description: d });
  const tool = { name: 'read_photo', description: 'Describe the item in the photo for a resale search.', input_schema: { type: 'object', required: ['search', 'details'], properties: {
    brand: str('Brand, if you can tell from logos, tags or the design; else empty'), line: str('Line or sub-label, if clear'), model: str('Model or product name, if clear'),
    category: { type: 'string', enum: [...cats, 'other'] }, colour: str('Main colour, one or two words'),
    era: { type: 'string', enum: ['', '70s', '80s', '90s', '00s', 'Y2K'] },
    search: str('The search to run, at most 6 words: brand and model name if known (e.g. "Deiji Studios Pintuck Jacket"), else 2 or 3 telling words and the garment. Never a long description'),
    search_ja: str('The same search as Japanese resale sellers would write it, in katakana where usual'),
    details: str('At most 14 words: what it is and what sets it apart'),
    sure: { type: 'boolean', description: 'True only if the brand is clear from a logo, tag or a famous design' },
  } } };
  const { call, error } = await askClaude(env, 'You identify clothing and accessories from photos for second-hand searches. Name a brand when a logo, tag or very well-known design shows it, or when the web matches given agree on it; otherwise describe the item briefly.',
    [{ type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: photo } }, { type: 'text', text: 'What is this, and how would someone search for it?' +
      (strList(body.web, 20, 140).length ? '\nGoogle Lens found these pages showing a similar picture (title | site). If several agree on a brand and product name, it is very likely this item:\n' + strList(body.web, 20, 140).join('\n') : '') }], tool, 500);
  if (error) return { error };
  const i = (call && call.input) || {};
  return { photo: { brand: shortText(i.brand, 60), line: shortText(i.line, 60), model: shortText(i.model, 60), category: cats.includes(i.category) ? i.category : '', colour: shortText(i.colour, 30),
    era: ['70s', '80s', '90s', '00s', 'Y2K'].includes(i.era) ? i.era : '', search: shortText(i.search, 100), search_ja: shortText(i.search_ja, 100), details: shortText(i.details, 140), sure: !!i.sure } };
}

// Small independent shops likely to stock this, by web address.
// Learning from results: which of the brand's own product names, seen in the listings found, are the item searched?
// ("DVN backzip" → the titles keep saying "Harson Back Zip Sweater", so Harson is searched and kept too.)
async function claudeModels(body, env) {
  const q = shortText(body.query, 100), brand = shortText(body.brand, 60);
  const titles = strList(body.titles, 80, 140);
  if (!q || titles.length < 2) return { names: [] };
  const tool = { name: 'models', description: 'Product names that are the item searched.', input_schema: { type: 'object', required: ['names'], properties: {
    names: { type: 'array', items: { type: 'string' }, description: 'The brand\'s own product or style names (one or two words each, as written in the titles) for pieces that are what the search describes. Not colours, materials, garment types, seasons, sizes, condition words, the brand itself, or words the search already contains. Only names that appear in at least two titles. Usually zero to three names.' },
  } } };
  const { call, error } = await askClaude(env, 'You know fashion brands\' product and style names. You pick, from listing titles, the names a brand uses for the item a shopper searched for, so the search can include listings that use the name but not the shopper\'s words.',
    [{ type: 'text', text: `Search: ${q}\nBrand: ${brand}\nTitles found:\n${titles.map(t => '- ' + t).join('\n')}` }], tool, 300);
  if (error) return { error };
  const said = q.toLowerCase();
  const names = strList(call && call.input && call.input.names, 4, 40).filter(n => !said.includes(n.toLowerCase()) && titles.filter(t => t.toLowerCase().includes(n.toLowerCase())).length >= 2);
  return { names };
}
async function claudeShops(body, env) {
  const q = shortText(body.query, 120);
  if (!q) return { error: 'Nothing to look for' };
  const tool = { name: 'shops', description: 'List shop web addresses.', input_schema: { type: 'object', required: ['domains'], properties: { domains: { type: 'array', items: { type: 'string' }, description: 'Bare domains, e.g. example.com' } } } };
  const { call, error } = await askClaude(env, 'You know independent online clothing shops worldwide: vintage, archive, designer resale, surf and outdoor boutiques, and brand stores, including Japanese and Australian ones. Only list shops you are confident exist and sell online. No marketplaces (eBay, Grailed, Depop, Mercari and the like) and no big department stores.',
    [{ type: 'text', text: `Up to 8 shops likely to stock: ${q}${body.about ? ' (' + shortText(body.about, 160) + ')' : ''}` }], tool, 300);
  if (error) return { error };
  const domains = strList(call && call.input && call.input.domains, 8, 64).map(d => d.toLowerCase().replace(/^https?:\/\//, '').replace(/[/?#].*$/, '').replace(/^www\./, '')).filter(goodDomain).filter(d => !BIG_SITES.test(d + '.'));
  return { domains };
}

async function apiSearch(url, env, ctx) {
  const site = url.searchParams.get('site') || '', domain = (url.searchParams.get('domain') || '').toLowerCase().slice(0, 80);
  const term = (url.searchParams.get('term') || '').trim().slice(0, 120);
  const page = (url.searchParams.get('page') || '1').slice(0, 200);
  const def = SITES[site];
  const fail = (error, status = 200) => json({ listings: [], next: null, error }, url, 0, status);
  if (!def) return fail('Unknown site', 400);
  if (!term) return fail('No search term', 400);
  if (!def.search || !def.enabled || disabledSet(env).has(site)) return fail(def.reason || 'Connector switched off');

  // 15-minute cache. The Cache API does nothing on *.workers.dev addresses, so the
  // response also carries max-age=900 and the browser's own cache does the same job there.
  const cacheKey = new Request(`${url.origin}/api/search?site=${enc(site)}&domain=${enc(domain)}&term=${enc(term)}&page=${enc(page)}`);
  let cache = null;
  try { cache = caches.default; } catch (e) { cache = null; }
  if (cache) {
    const hit = await cache.match(cacheKey).catch(() => null);
    if (hit) {
      const res = new Response(hit.body, hit);
      res.headers.set('x-vgf-cache', 'HIT');
      return res;
    }
  }
  try {
    const out = await def.search(term, page, env, domain);
    health[site] = { ok: true, at: Date.now() };
    const tag = site === 'shop' || site === 'woo' ? site + ':' + domain : site === 'siteweb' ? 'web' : site;
    const seen = new Set();
    const listings = out.listings
      .filter(l => l.id && l.title && !seen.has(l.id) && seen.add(l.id))
      .slice(0, MAX_LISTINGS)
      .map(l => ({ site: tag, id: l.id, url: l.url, title: l.title, price: l.price, currency: l.currency, ...(l.was ? { was: l.was } : {}), ...(l.auction ? { auction: true } : {}), image: l.image || '', size: l.size || '', extra: l.extra || {}, term }));
    const res = json({ listings, next: out.next == null ? null : out.next }, url, CACHE_SECONDS);
    if (cache && ctx && ctx.waitUntil) ctx.waitUntil(cache.put(cacheKey, res.clone()).catch(() => {}));
    return res;
  } catch (e) {
    const error = String((e && e.message) || e).slice(0, 200);
    health[site] = { ok: false, at: Date.now(), error };
    return fail(error);
  }
}

// Listing photos, passed through so the browser may compare them with the user's photo.
// Only marketplace image hosts are allowed, so this cannot be used as an open proxy.
const IMAGE_HOSTS = ['yimg.jp', 'fril.jp', 'grailed.com', 'ebayimg.com', 'mercdn.net', 'depop.com', 'shopify.com', 'gstatic.com', 'vinted.net', 'serpapi.com', 'googleusercontent.com'];

async function apiImage(url) {
  let target;
  try { target = new URL(url.searchParams.get('u') || ''); } catch (e) { return new Response('Bad image address', { status: 400 }); }
  const host = target.hostname.toLowerCase();
  if (target.protocol !== 'https:' || !IMAGE_HOSTS.some(h => host === h || host.endsWith('.' + h))) return new Response('Image host not allowed', { status: 403 });
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(), TIMEOUT_MS);
  try {
    const res = await fetch(target.toString(), { signal: ac.signal, headers: { 'user-agent': UA, accept: 'image/avif,image/webp,image/*;q=0.8' } });
    const type = res.headers.get('content-type') || '';
    if (!res.ok || !type.startsWith('image/')) return new Response('Image unavailable', { status: 502 });
    if (+(res.headers.get('content-length') || 0) > 6e6) return new Response('Image too large', { status: 413 });
    return new Response(res.body, { headers: { 'content-type': type, 'cache-control': 'public, max-age=86400', 'x-content-type-options': 'nosniff', ...cors(url) } });
  } catch (e) {
    return new Response('Image unavailable', { status: 502 });
  } finally {
    clearTimeout(timer);
  }
}

// ---------- shared helpers ----------

// One polite fetch: browser User-Agent, no cookies, 10 s timeout, one retry.
async function get(url, opt = {}, as = 'text', tries = 2) {
  let err;
  for (let i = 0; i < tries; i++) {
    const ac = new AbortController();
    const timer = setTimeout(() => ac.abort(), TIMEOUT_MS);
    try {
      const res = await fetch(url, {
        method: opt.method || 'GET',
        body: opt.body,
        signal: ac.signal,
        headers: {
          'user-agent': UA,
          'accept-language': 'ja,en-US;q=0.9,en;q=0.8',
          accept: as === 'json' ? 'application/json' : 'text/html,application/xhtml+xml',
          ...(opt.headers || {}),
        },
      });
      if (!res.ok) {
        const why = res.status === 400 || res.status === 422 ? (await res.text().catch(() => '')).replace(/\s+/g, ' ').slice(0, 120) : '';
        const e = new Error(res.status === 403 || res.status === 429 ? `Blocked (HTTP ${res.status})` : `HTTP ${res.status}${why ? ': ' + why : ''}`);
        e.status = res.status;
        if (res.status === 400 || res.status === 404) { err = e; break; } // asking again won't change the answer
        throw e;
      }
      return as === 'json' ? await res.json() : await res.text();
    } catch (e) {
      err = e && e.name === 'AbortError' ? new Error('Timed out after 10 s') : e;
    } finally {
      clearTimeout(timer);
    }
  }
  throw err;
}
// Some sites answer "404" when a search simply has no results.
const emptyOn404 = p => p.catch(e => { if (e.status === 404) return null; throw e; });

const pageNum = (p, max) => Math.min(Math.max(parseInt(p, 10) || 1, 1), max);
const num = v => {
  if (typeof v === 'number') return v;
  if (v && typeof v === 'object') v = v.value ?? v.amount ?? v.price ?? '';
  const n = parseFloat(String(v ?? '').replace(/[^\d.]/g, ''));
  return isFinite(n) ? n : 0;
};
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };
const unesc = s => String(s || '').replace(/&(#x?[0-9a-f]+|[a-z]+);/gi, (m, e) => {
  if (e[0] !== '#') return ENT[e.toLowerCase()] ?? m;
  const code = e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
  return code > 0 && code < 0x110000 ? String.fromCodePoint(code) : m;
});
const strip = s => unesc(String(s || '').replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();
const dig = (o, path) => path.split('.').reduce((v, k) => (v == null ? v : v[k]), o);

// The JSON that Next.js sites embed in <script id="__NEXT_DATA__">.
function nextData(html) {
  const i = html.indexOf('id="__NEXT_DATA__"');
  if (i < 0) throw new Error('Page layout changed (no embedded data)');
  const start = html.indexOf('>', i) + 1;
  return JSON.parse(html.slice(start, html.indexOf('</script>', start)));
}

// Breadth-first walk for the first array whose objects carry all of `keys`.
function findArray(root, keys) {
  const queue = [root];
  for (let i = 0; i < queue.length && i < 40000; i++) {
    const v = queue[i];
    if (Array.isArray(v)) {
      const first = v[0];
      if (first && typeof first === 'object' && keys.every(k => k in first)) return v;
      for (let j = 0; j < v.length && j < 3; j++) if (v[j] && typeof v[j] === 'object') queue.push(v[j]);
    } else if (v && typeof v === 'object') {
      for (const k in v) if (v[k] && typeof v[k] === 'object') queue.push(v[k]);
    }
  }
  return null;
}

function pickImage(it) {
  for (const k of ['thumbnailImageUrl', 'imageUrl', 'thumbnailUrl', 'thumbnail', 'image', 'img', 'images', 'thumbnails']) {
    let v = it[k];
    if (Array.isArray(v)) v = v[0];
    if (v && typeof v === 'object') v = v.url || v.imageUrl || v.src;
    if (typeof v === 'string' && v) return v;
  }
  for (const k in it) if (typeof it[k] === 'string' && /^https?:\/\/\S+\.(jpe?g|png|webp)/i.test(it[k])) return it[k];
  return '';
}

function parseMoney(text, dollar = 'USD') {
  const t = String(text || '');
  const m = t.match(/[\d][\d,]*(?:\.\d+)?/);
  const currency = /A(?:U)?\s*\$|AUD/.test(t) ? 'AUD' : /C\s*\$|CAD/.test(t) ? 'CAD' : /US\s*\$|USD/.test(t) ? 'USD' : /£|GBP/.test(t) ? 'GBP' : /€|EUR/.test(t) ? 'EUR' : /¥|JPY|円/.test(t) ? 'JPY' : dollar;
  return { price: m ? parseFloat(m[0].replace(/,/g, '')) : 0, currency };
}

// ---------- Yahoo Auctions JP ----------

async function yahooAuctions(term, page) {
  const p = pageNum(page, MAX_PAGE);
  const html = await get(`https://auctions.yahoo.co.jp/search/search/${enc(term)}/0?fixed=0&n=100&b=${(p - 1) * 100 + 1}`);
  const data = nextData(html);
  let items = dig(data, 'props.pageProps.initialState.search.items.listing.items');
  if (!Array.isArray(items)) items = findArray(data, ['auctionId', 'title']) || [];
  const listings = items.map(it => ({
    id: String(it.auctionId || ''),
    url: `https://auctions.yahoo.co.jp/jp/auction/${it.auctionId}`,
    title: strip(it.title),
    price: num(it.price),
    currency: 'JPY',
    image: it.imageUrl || pickImage(it),
    auction: !(num(it.buyNowPrice) && num(it.buyNowPrice) === num(it.price) && !num(it.bidCount)) || undefined,
    extra: { bids: num(it.bidCount), ends: it.endTime || '', buyNow: num(it.buyNowPrice) || undefined, proxy: `https://buyee.jp/item/yahoo/auction/${it.auctionId}` },
  }));
  return { listings, next: items.length >= 100 && p < MAX_PAGE ? p + 1 : null };
}

// ---------- Yahoo Flea Market (PayPay) JP ----------

async function yahooFlea(term, page) {
  const p = pageNum(page, MAX_PAGE);
  const html = await emptyOn404(get(`https://paypayfleamarket.yahoo.co.jp/search/${enc(term)}?open=1&page=${p}`));
  if (!html) return { listings: [], next: null };
  const items = findArray(nextData(html), ['id', 'title', 'price']) || [];
  const listings = items.map(it => ({
    id: String(it.id),
    url: `https://paypayfleamarket.yahoo.co.jp/item/${it.id}`,
    title: strip(it.title),
    price: num(it.price),
    currency: 'JPY',
    image: pickImage(it),
  }));
  return { listings, next: items.length && p < MAX_PAGE ? p + 1 : null };
}

// ---------- Rakuma JP (server-rendered HTML) ----------

// The whole <a ...> tag around position idx, honouring quoted attribute values.
function tagAround(html, idx) {
  const start = html.lastIndexOf('<a', idx);
  let quote = '', i = start;
  for (; i < html.length; i++) {
    const c = html[i];
    if (quote) { if (c === quote) quote = ''; }
    else if (c === '"' || c === "'") quote = c;
    else if (c === '>') break;
  }
  return { tag: html.slice(start, i + 1), end: i + 1 };
}

function attr(tag, name) {
  const m = tag.match(new RegExp('[\\s"\']' + name + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\')', 'i'));
  return m ? unesc(m[1] ?? m[2]) : '';
}

// One field out of the dataLayer JSON in an onclick, whichever quote style it uses.
function jsField(src, key) {
  const m = src.match(new RegExp('["\']?' + key + '["\']?\\s*:\\s*(?:"((?:[^"\\\\]|\\\\.)*)"|\'((?:[^\'\\\\]|\\\\.)*)\'|([\\d.]+))'));
  if (!m) return '';
  if (m[3] != null) return m[3];
  const raw = m[1] != null ? m[1] : m[2].replace(/\\'/g, "'").replace(/"/g, '\\"');
  try { return JSON.parse('"' + raw + '"'); } catch (e) { return raw; }
}

async function rakuma(term, page) {
  const p = pageNum(page, MAX_PAGE);
  const html = await emptyOn404(get(`https://fril.jp/s?query=${enc(term)}&transaction=selling&page=${p}`));
  if (!html) return { listings: [], next: null };
  const marks = [];
  for (let i = html.indexOf('link_search_image'); i >= 0; i = html.indexOf('link_search_image', i + 1)) marks.push(i);
  const listings = [];
  marks.forEach((mark, k) => {
    const { tag, end } = tagAround(html, mark);
    const href = attr(tag, 'href');
    if (!tag.startsWith('<a') || !href) return;
    const inner = html.slice(end, Math.min(marks[k + 1] || html.length, end + 4000));
    const onclick = attr(tag, 'onclick');
    const id = (href.split(/[?#]/)[0].match(/([^/]+)\/?$/) || [])[1] || '';
    const title = jsField(onclick, 'item_name') || unesc((inner.match(/<img[^>]+alt=["']([^"']*)/i) || [])[1]);
    const price = num(jsField(onclick, 'price')) || num((inner.match(/[¥￥]\s*([\d,]+)/) || [])[1]);
    listings.push({
      id,
      url: href.startsWith('http') ? href : 'https://fril.jp' + href,
      title: strip(title),
      price,
      currency: 'JPY',
      image: unesc((inner.match(/data-original=["']([^"']+)/i) || inner.match(/<img[^>]+src=["']([^"']+)/i) || [])[1]),
      extra: { brand: jsField(onclick, 'brand_name') || undefined },
    });
  });
  return { listings, next: listings.length >= 40 && p < MAX_PAGE ? p + 1 : null };
}

// ---------- eBay (official Browse API, HTML as the fallback) ----------

let ebayToken = null;

async function ebayAuth(env) {
  if (ebayToken && ebayToken.exp > Date.now() + 60000) return ebayToken.token;
  // pasted keys often carry a space or line break; eBay then rejects the pair
  const id = String(env.EBAY_CLIENT_ID).trim(), secret = String(env.EBAY_CLIENT_SECRET).trim();
  if (/-SBX-/i.test(id)) throw new Error('these are Sandbox keys; use the Production keyset (its App ID has PRD in it)');
  const res = await fetch('https://api.ebay.com/identity/v1/oauth2/token', {
    method: 'POST',
    headers: { authorization: 'Basic ' + btoa(`${id}:${secret}`), 'content-type': 'application/x-www-form-urlencoded', 'user-agent': UA },
    body: 'grant_type=client_credentials&scope=' + enc('https://api.ebay.com/oauth/api_scope'),
  });
  const d = await res.json().catch(() => ({}));
  if (!res.ok || !d.access_token) {
    const why = [d.error, d.error_description].filter(Boolean).join(': ');
    throw new Error(`eBay refused the keys (HTTP ${res.status}${why ? ', ' + why : ''}). Check EBAY_CLIENT_ID is the App ID and EBAY_CLIENT_SECRET is the Cert ID from the same Production keyset`);
  }
  ebayToken = { token: d.access_token, exp: Date.now() + (d.expires_in || 7200) * 1000 };
  return ebayToken.token;
}

async function ebayApi(term, p, env) {
  const d = await get(`https://api.ebay.com/buy/browse/v1/item_summary/search?q=${enc(term)}&limit=200&offset=${(p - 1) * 200}`, {
    headers: { authorization: 'Bearer ' + (await ebayAuth(env)), 'x-ebay-c-marketplace-id': String(env.EBAY_MARKETPLACE || 'EBAY_US').trim().toUpperCase() },
  }, 'json');
  const items = d.itemSummaries || [];
  const listings = items.map(it => {
    const auction = (it.buyingOptions || []).includes('AUCTION');
    const money = (auction && it.currentBidPrice) || it.price || it.currentBidPrice || {};
    const orig = it.marketingPrice && it.marketingPrice.originalPrice;
    const id = it.legacyItemId || String(it.itemId || '').split('|')[1] || String(it.itemId || '');
    return {
      id,
      url: it.itemWebUrl || `https://www.ebay.com/itm/${id}`,
      title: strip(it.title),
      price: num(money.value),
      currency: money.currency || 'USD',
      was: wasPrice(orig && orig.currency === money.currency ? num(orig.value) : 0, num(money.value)),
      auction: auction || undefined,
      image: (it.image && it.image.imageUrl) || (it.thumbnailImages && it.thumbnailImages[0] && it.thumbnailImages[0].imageUrl) || '',
      extra: { condition: it.condition || undefined, country: (it.itemLocation && it.itemLocation.country) || undefined, bids: auction ? num(it.bidCount) || 0 : undefined, ends: auction ? it.itemEndDate || '' : undefined },
    };
  });
  return { listings, next: d.next && p < MAX_PAGE ? p + 1 : null };
}

async function ebayHtml(term, p) {
  const html = await get(`https://www.ebay.com/sch/i.html?_nkw=${enc(term)}&_ipg=240&_pgn=${p}`);
  const parts = html.split('data-listingid=');
  const listings = [];
  const textAt = (body, cls) => {
    const i = body.indexOf(cls);
    if (i < 0) return '';
    const start = body.indexOf('>', i) + 1;
    return strip(body.slice(start, start + 600).split('</div>')[0]).replace(/^new listing\s*/i, '').replace(/\s*opens in a new window or tab\s*$/i, '');
  };
  for (let k = 1; k < parts.length; k++) {
    const body = parts[k].slice(0, 8000);
    const id = (body.match(/^["']?(\d{9,})/) || [])[1];
    const title = textAt(body, 's-card__title');
    if (!id || !title || /^shop on ebay/i.test(title)) continue; // ghost rows
    const money = parseMoney(textAt(body, 's-card__price'));
    const bids = (strip(body).match(/\b(\d+)\s+bids?\b/i) || [])[1];
    const struck = (body.match(/(?:STRIKETHROUGH|strikethrough|s-card__price--previous)[^>]*>([^<]{2,40})/) || [])[1];
    const was = struck ? parseMoney(strip(struck)) : null;
    listings.push({
      id,
      url: `https://www.ebay.com/itm/${id}`,
      title,
      price: money.price,
      currency: money.currency,
      was: was && was.currency === money.currency ? wasPrice(was.price, money.price) : undefined,
      auction: bids != null || undefined,
      image: unesc((body.match(/<img[^>]+(?:data-src|src)=["'](https?:[^"']+)/i) || [])[1]),
    });
  }
  if (!listings.length && /captcha|pardon our interruption/i.test(html)) throw new Error('Blocked (eBay asked for a captcha)');
  return { listings, next: listings.length >= 200 && p < MAX_PAGE ? p + 1 : null };
}

async function ebay(term, page, env) {
  const p = pageNum(page, MAX_PAGE);
  if (!env.EBAY_CLIENT_ID || !env.EBAY_CLIENT_SECRET) return ebayHtml(term, p);
  try {
    return await ebayApi(term, p, env);
  } catch (apiErr) {
    try { return await ebayHtml(term, p); } catch (e) { throw new Error(`eBay API: ${apiErr.message}. HTML fallback: ${e.message}`); }
  }
}

// ---------- Grailed (Algolia) ----------

let grailedKeys = null;

async function grailedCreds(env) {
  if (env.GRAILED_ALGOLIA_APP_ID && env.GRAILED_ALGOLIA_KEY) return { app: env.GRAILED_ALGOLIA_APP_ID, key: env.GRAILED_ALGOLIA_KEY };
  if (grailedKeys) return grailedKeys;
  // Not set as Worker variables: try once to read the public keys from Grailed's page source.
  const html = await get('https://www.grailed.com/shop');
  const app = (html.match(/app(?:lication)?_?id\\?["']?\s*[:=]\s*\\?["']([A-Z0-9]{10})\\?["']/i) || [])[1];
  const key = (html.match(/(?:search_?(?:only_?)?(?:api_?)?key|api_?key)\\?["']?\s*[:=]\s*\\?["']([a-f0-9]{32})\\?["']/i) || [])[1];
  if (!app || !key) throw new Error('Grailed keys not set. Add GRAILED_ALGOLIA_APP_ID and GRAILED_ALGOLIA_KEY in the Worker settings.');
  return (grailedKeys = { app, key });
}

async function grailed(term, page, env) {
  const p = pageNum(page, MAX_PAGE);
  const { app, key } = await grailedCreds(env);
  const index = env.GRAILED_INDEX || 'Listing_by_heat_production';
  const d = await get(`https://${app.toLowerCase()}-dsn.algolia.net/1/indexes/${enc(index)}/query`, {
    method: 'POST',
    headers: { 'x-algolia-application-id': app, 'x-algolia-api-key': key, 'content-type': 'application/json', origin: 'https://www.grailed.com', referer: 'https://www.grailed.com/' },
    body: JSON.stringify({ query: term, hitsPerPage: 250, page: p - 1 }), // bigger pages: fewer round trips
  }, 'json');
  const listings = (d.hits || []).map(it => ({
    id: String(it.id),
    url: `https://www.grailed.com/listings/${it.id}`,
    title: strip(it.title),
    price: num(it.price),
    currency: 'USD',
    was: wasPrice(Math.max(0, ...[it.original_price, ...(Array.isArray(it.price_drops) ? it.price_drops : [])].map(num).filter(Boolean)), num(it.price)),
    image: (it.cover_photo && it.cover_photo.url) || '',
    size: it.size ? String(it.size).toUpperCase() : '',
    extra: { brand: (it.designers || []).map(x => x.name).filter(Boolean).join(' ') || it.designer_names || undefined },
  }));
  return { listings, next: p < Math.min(d.nbPages || 1, MAX_PAGE) ? p + 1 : null };
}

// ---------- Depop ----------


// ---------- Mercari JP (private search API, signed with a DPoP header) ----------
// Ported from the open-source `mercapi` Python library. Most likely connector to break.

let mercariKey = null;
const b64url = bytes => btoa(String.fromCharCode(...bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

async function dpop(url, method) {
  if (!mercariKey) {
    const pair = await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify']);
    const jwk = await crypto.subtle.exportKey('jwk', pair.publicKey);
    mercariKey = { key: pair.privateKey, jwk: { crv: jwk.crv, kty: jwk.kty, x: jwk.x, y: jwk.y }, uuid: crypto.randomUUID() };
  }
  const part = o => b64url(new TextEncoder().encode(JSON.stringify(o)));
  const head = part({ typ: 'dpop+jwt', alg: 'ES256', jwk: mercariKey.jwk });
  const body = part({ iat: Math.floor(Date.now() / 1000), jti: crypto.randomUUID(), htu: url, htm: method, uuid: mercariKey.uuid });
  const sig = await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, mercariKey.key, new TextEncoder().encode(`${head}.${body}`));
  return `${head}.${body}.${b64url(new Uint8Array(sig))}`;
}

async function mercari(term, page) {
  const p = pageNum(page, MAX_PAGE);
  const api = 'https://api.mercari.jp/v2/entities:search';
  const payload = JSON.stringify({
    userId: '',
    pageSize: 120,
    pageToken: p > 1 ? `v1:${p - 1}` : '',
    searchSessionId: crypto.randomUUID().replace(/-/g, ''),
    indexRouting: 'INDEX_ROUTING_UNSPECIFIED',
    thumbnailTypes: [],
    searchCondition: {
      keyword: term, excludeKeyword: '', sort: 'SORT_SCORE', order: 'ORDER_DESC', status: ['STATUS_ON_SALE'],
      sizeId: [], categoryId: [], brandId: [], sellerId: [], priceMin: 0, priceMax: 0, itemConditionId: [],
      shippingPayerId: [], shippingFromArea: [], shippingMethod: [], colorId: [], hasCoupon: false, attributes: [], itemTypes: [], skuIds: [],
    },
    defaultDatasets: ['DATASET_TYPE_MERCARI', 'DATASET_TYPE_BEYOND'],
    serviceFrom: 'suruga',
    withItemBrand: true, withItemSize: false, withItemPromotions: true, withItemSizes: true, withShopname: false,
  });
  let d, err;
  for (let i = 0; i < 2 && !d; i++) { // a fresh signature for each try
    try {
      d = await get(api, { method: 'POST', body: payload, headers: { dpop: await dpop(api, 'POST'), 'x-platform': 'web', 'content-type': 'application/json; charset=utf-8', origin: 'https://jp.mercari.com', referer: 'https://jp.mercari.com/' } }, 'json', 1);
    } catch (e) { err = e; }
  }
  if (!d) throw err;
  const items = d.items || [];
  const listings = items.map(it => {
    const shop = it.itemType === 'ITEM_TYPE_BEYOND' || !/^m\d+$/.test(String(it.id));
    return {
      id: String(it.id),
      url: shop ? `https://jp.mercari.com/shops/product/${it.id}` : `https://jp.mercari.com/item/${it.id}`,
      title: strip(it.name),
      price: num(it.price),
      currency: 'JPY',
      image: (it.thumbnails && it.thumbnails[0]) || '',
      size: (it.itemSizes && it.itemSizes[0] && it.itemSizes[0].name) || (it.itemSize && it.itemSize.name) || '',
      extra: { brand: (it.itemBrand && [it.itemBrand.name, it.itemBrand.subName].filter(Boolean).join(' ')) || undefined, proxy: shop ? undefined : `https://buyee.jp/mercari/item/${it.id}` },
    };
  });
  return { listings, next: d.meta && d.meta.nextPageToken && items.length && p < MAX_PAGE ? p + 1 : null };
}

// ---------- Google Shopping (through serper.dev, which needs a key) ----------
// Finds new and second-hand listings at shops such as SSENSE, Cettire, Farfetch and brand sites.
const COUNTRY_CURRENCY = { au: 'AUD', us: 'USD', ca: 'CAD', nz: 'NZD', gb: 'GBP', jp: 'JPY' };

async function googleShopping(term, page, env) {
  if (!env.SERPER_API_KEY) throw new Error('No SERPER_API_KEY set');
  const gl = String(env.SERPER_COUNTRY || 'au').toLowerCase();
  const d = await get('https://google.serper.dev/shopping', {
    method: 'POST',
    headers: { 'x-api-key': env.SERPER_API_KEY, 'content-type': 'application/json' },
    body: JSON.stringify({ q: term, gl, hl: 'en', page: pageNum(page, MAX_PAGE) }),
  }, 'json', 1); // no retry: every call uses a search credit
  const listings = (d.shopping || []).map((it, i) => {
    const money = parseMoney(it.price, COUNTRY_CURRENCY[gl] || 'USD');
    return {
      id: String(it.productId || it.link || i),
      url: it.link,
      title: strip(it.title),
      price: money.price,
      currency: money.currency,
      was: wasPrice(parseMoney(it.originalPrice || it.oldPrice || it.old_price || '', money.currency).price, money.price),
      image: it.imageUrl || '',
      extra: { shop: it.source || undefined, delivery: it.delivery || undefined },
    };
  }).filter(l => /^https?:\/\//.test(l.url || ''));
  return { listings, next: null };
}

// ---------- Depop and Vinted, through Google (both screen out servers like this one) ----------
// One Google page per term (each is a Serper credit). Titles, links and usually a price; not always a photo.
async function serperWeb(q, env, num = 10, page = 1) {
  if (!env.SERPER_API_KEY) throw new Error('No SERPER_API_KEY set');
  return get('https://google.serper.dev/search', {
    method: 'POST', headers: { 'x-api-key': env.SERPER_API_KEY, 'content-type': 'application/json' },
    body: JSON.stringify({ q, gl: String(env.SERPER_COUNTRY || 'au').toLowerCase(), hl: 'en', ...(num === 10 ? {} : { num }), ...(page > 1 ? { page } : {}) }),
  }, 'json', 1);
}
const PRICE_IN_TEXT = /(?:A\$|AU\$|US\$|C\$|£|€|\$)\s?\d[\d,]*(?:\.\d{2})?|\d[\d,]*(?:\.\d{2})?\s?(?:AUD|USD|GBP|EUR)\b/i;
// "Pintuck Jacket | NET-A-PORTER" → "Pintuck Jacket"; a " - " ending is cut only when it is the site's own name
function siteless(t, link) {
  const dom = domainOf(link).replace(/\.[a-z.]+$/, '').replace(/[^a-z0-9]/g, '');
  t = t.replace(/\s+[|·–—]\s+[^|·–—]{2,40}$/, '').trim();
  const m = t.match(/\s+-\s+([^-]{2,40})$/);
  if (m && dom.length > 2 && m[1].toLowerCase().replace(/[^a-z0-9]/g, '').includes(dom.slice(0, 6))) t = t.slice(0, m.index).trim();
  return t;
}
function organicListing(o, i, dollar) {
  const attrs = o.attributes || {};
  const priceText = String(o.price || attrs.Price || attrs.price || (String(o.snippet || '').match(PRICE_IN_TEXT) || [])[0] || '');
  const money = parseMoney(priceText, /vinted\.com\//.test(o.link) ? 'USD' : /\.au\//.test(o.link + '/') ? 'AUD' : dollar);
  return {
    id: String(o.link).replace(/[?#].*$/, '') || String(i), url: o.link,
    title: siteless(strip(o.title || ''), o.link),
    price: money.price, currency: money.currency, image: o.imageUrl || o.thumbnailUrl || '',
    extra: { snippet: strip(o.snippet || '').slice(0, 160) || undefined, viaGoogle: true, shop: domainOf(o.link) },
  };
}
async function viaGoogle(term, env, o) {
  let d;
  try { d = await serperWeb(`${o.filter} ${term}`, env); }
  catch (e) { // if Google refuses the site: filter, ask plainly and keep only that site's item pages
    if (e.status !== 400) throw e;
    d = await serperWeb(`${term} ${o.word}`, env);
  }
  const listings = (d.organic || []).filter(r => o.link.test(r.link || '')).map((r, i) => organicListing(r, i, o.dollar)).filter(l => l.title);
  return { listings, next: null };
}
// Everything Google shows for the search: product pages on any shop (prices are read from the page afterwards)
const NOT_SHOPS = /(^|\.)(wear\.jp|wear|snap|lookbook|wikipedia|youtube|instagram|facebook|pinterest|tiktok|reddit|x|twitter|threads|linkedin|vogue|gq|hypebeast|highsnobiety|whowhatwear|refinery29|elle|harpersbazaar|medium|substack|tumblr|quora|google|apple|spotify|imdb|news|theguardian|smh|abc)\./i;
const NOT_ITEMS = /\/(collections?|categor(y|ies)|c|brands?|designers?|search|blog|blogs|journal|stories|news|about|pages|tags?|stockists?)(\/|$)|[?&](q|query|search)=/i;
// Every page Google has indexed for the search on one shop (e.g. "site:constant-practice.com kiko stussy"):
// reaches shops whose own search can't be read, like Shopify shops with a custom front end
async function googleOneShop(term, page, env, domain) {
  if (!goodDomain(domain) || /^[\d.]+$/.test(domain)) throw new Error('Not a shop address');
  const p = pageNum(page, 3);
  const d = await serperWeb(`site:${domain} ${term}`, env, 10, p);
  const listings = (d.organic || []).filter(r => {
    let u; try { u = new URL(r.link); } catch (e) { return false; }
    return u.hostname.replace(/^www\./, '').endsWith(domain.replace(/^www\./, '')) && u.pathname.length > 2 && (/\/products?\//i.test(u.pathname) || !NOT_ITEMS.test(u.pathname + u.search));
  }).map((r, i) => organicListing(r, i, /\.au$/.test(domain) ? 'AUD' : 'USD')).filter(l => l.title);
  return { listings, next: (d.organic || []).length >= 8 && p < 3 ? String(p + 1) : null };
}
async function googleWeb(term, page, env) {
  const p = pageNum(page, 3);
  const d = await serperWeb(term, env, 10, p);
  const listings = (d.organic || []).filter(r => {
    let u; try { u = new URL(r.link); } catch (e) { return false; }
    if (NOT_SHOPS.test(u.hostname + '.') || u.pathname.length < 3) return false;
    return /\/products?\//i.test(u.pathname) || !NOT_ITEMS.test(u.pathname + u.search);
  }).map((r, i) => organicListing(r, i, 'USD')).filter(l => l.title);
  return { listings, next: (d.organic || []).length >= 8 && p < 3 ? String(p + 1) : null };
}

// ---------- Finding more shops: which sites sell this, and which of them can be searched ----------
const BIG_SITES = /(^|\.)(ebay|grailed|depop|vinted|mercari|yahoo|rakuten|amazon|etsy|poshmark|farfetch|ssense|cettire|endclothing|lyst|pinterest|instagram|facebook|reddit|youtube|tiktok|wikipedia|vestiaire(collective)?|therealreal|google|apple|zalando|asos|net-a-porter|mytheresa|matchesfashion|thredup|fril|buyee|zenmarket|2ndstreet|x|twitter|stockx|goat|klekt|hypebeast|highsnobiety|vogue|gq|quora|medium|tumblr|flickr|shopify|walmart|target|aliexpress|temu|shein|dhgate|carousell|gumtree|craigslist|whatnot|vinted|tradera|kleinanzeigen|leboncoin|marketplace)\./i;
const domainOf = u => { try { return new URL(u).hostname.toLowerCase().replace(/^www\./, ''); } catch (e) { return ''; } };
const goodDomain = d => /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(d) && d.length < 64;
async function apiDiscover(url, env) {
  const q = (url.searchParams.get('q') || '').trim().slice(0, 120);
  if (!q) return json({ shops: [], error: 'Nothing to look for' }, url, 0, 400);
  if (!env.SERPER_API_KEY) return json({ shops: [], error: 'Add a SERPER_API_KEY secret to find more shops.' }, url, 0);
  try {
    const d = await serperWeb(`${q} buy online shop`, env, 30);
    const seen = new Set(), shops = [];
    for (const o of d.organic || []) {
      const dom = domainOf(o.link);
      if (!goodDomain(dom) || seen.has(dom) || BIG_SITES.test(dom + '.')) continue;
      seen.add(dom); shops.push({ domain: dom, title: strip(o.title || '').slice(0, 80) });
    }
    return json({ shops: shops.slice(0, 12) }, url, 3600);
  } catch (e) { return json({ shops: [], error: e.message }, url, 0); }
}
// Is this site a shop we can search? Shopify answers /cart.js, WooCommerce answers its Store API.
async function apiProbe(url) {
  const dom = (url.searchParams.get('d') || '').toLowerCase().replace(/^https?:\/\//, '').replace(/[/?#].*$/, '').replace(/^www\./, '');
  if (!goodDomain(dom)) return json({ domain: dom, platform: null, error: 'Not a web address' }, url, 0, 400);
  let platform = null;
  for (const host of [dom, 'www.' + dom]) {
    try { const c = await get(`https://${host}/cart.js`, {}, 'json', 1); if (c && ('token' in c || 'item_count' in c)) { platform = 'shopify'; break; } } catch (e) { /* next */ }
    try { const w = await get(`https://${host}/wp-json/wc/store/v1/products?per_page=1`, {}, 'json', 1); if (Array.isArray(w)) { platform = 'woo'; break; } } catch (e) { /* next */ }
  }
  return json({ domain: dom, platform }, url, platform ? 86400 : 3600);
}

// ---------- the price on a product page (for Google Lens results, which often come without one) ----------
// Reads the structured data shops publish for Google (JSON-LD offers, price meta tags), or Shopify's product .js.
function pagePrice(html) {
  const out = {};
  const walk = (o, depth = 0) => {
    if (!o || typeof o !== 'object' || depth > 6 || out.price) return;
    if (Array.isArray(o)) { o.forEach(x => walk(x, depth + 1)); return; }
    const offers = o.offers ? [].concat(o.offers) : [];
    for (const of of offers) {
      if (!of || typeof of !== 'object') continue;
      const inner = of.offers ? [].concat(of.offers)[0] || {} : {};
      const pr = num(of.price ?? of.lowPrice ?? (of.priceSpecification && [].concat(of.priceSpecification)[0] || {}).price ?? inner.price);
      if (pr > 0) {
        out.price = pr; out.currency = String(of.priceCurrency || inner.priceCurrency || '').toUpperCase();
        out.soldOut = /OutOfStock|SoldOut|Discontinued/i.test(String(of.availability || inner.availability || '')) || undefined;
        return;
      }
    }
    for (const v of Object.values(o)) if (v && typeof v === 'object') walk(v, depth + 1);
  };
  for (const m of html.matchAll(/<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
    try { walk(JSON.parse(m[1].trim())); } catch (e) { /* broken JSON-LD */ }
    if (out.price) break;
  }
  const meta = name => { const m = html.match(new RegExp(`<meta[^>]+(?:property|name|itemprop)=["']${name}["'][^>]*content=["']([^"']+)`, 'i')) || html.match(new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]*(?:property|name|itemprop)=["']${name}["']`, 'i')); return m ? m[1] : ''; };
  if (!out.price) {
    const pr = num(meta('product:price:amount') || meta('og:price:amount') || meta('price'));
    if (pr > 0) { out.price = pr; out.currency = (meta('product:price:currency') || meta('og:price:currency') || meta('priceCurrency')).toUpperCase(); }
  }
  if (!out.currency) {
    const c = html.match(/Shopify\.currency\s*=\s*\{\s*"active"\s*:\s*"([A-Z]{3})"/) || html.match(/"priceCurrency"\s*:\s*"([A-Z]{3})"/);
    if (c) out.currency = c[1];
  }
  return out;
}
// Sites whose pages can't be read from here (eBay, Grailed): their own data has the price and picture
async function knownItem(u, env) {
  const host = u.hostname.replace(/^www\./, '').toLowerCase();
  const ebayId = /(^|\.)ebay\.[a-z.]+$/.test(host) && (u.pathname.match(/\/itm\/(?:[^/]+\/)?(\d{9,})/) || [])[1];
  if (ebayId && env.EBAY_CLIENT_ID && env.EBAY_CLIENT_SECRET) {
    const it = await get(`https://api.ebay.com/buy/browse/v1/item/get_item_by_legacy_id?legacy_item_id=${ebayId}`, {
      headers: { authorization: 'Bearer ' + (await ebayAuth(env)), 'x-ebay-c-marketplace-id': String(env.EBAY_MARKETPLACE || 'EBAY_US').trim().toUpperCase() },
    }, 'json', 1);
    const money = it.price || it.currentBidPrice || {}, orig = it.marketingPrice && it.marketingPrice.originalPrice;
    const avail = ((it.estimatedAvailabilities || [])[0] || {}).estimatedAvailabilityStatus;
    return { price: num(money.value), currency: money.currency || 'USD', image: (it.image && it.image.imageUrl) || '',
      was: wasPrice(orig && orig.currency === money.currency ? num(orig.value) : 0, num(money.value)), soldOut: avail === 'OUT_OF_STOCK' || undefined };
  }
  const grId = host === 'grailed.com' && (u.pathname.match(/\/listings\/(\d+)/) || [])[1];
  if (grId) {
    const { app, key } = await grailedCreds(env);
    const it = await get(`https://${app.toLowerCase()}-dsn.algolia.net/1/indexes/${enc(env.GRAILED_INDEX || 'Listing_by_heat_production')}/${grId}`, {
      headers: { 'x-algolia-application-id': app, 'x-algolia-api-key': key, origin: 'https://www.grailed.com', referer: 'https://www.grailed.com/' },
    }, 'json', 1);
    return { price: num(it.price), currency: 'USD', image: (it.cover_photo && it.cover_photo.url) || '', soldOut: it.sold ? true : undefined };
  }
  return null;
}
// Pages that block us or draw prices with scripts: Google Shopping for the same title (price only from the same
// shop), then Google Images on that shop for the picture. Each costs a search credit, so the app asks sparingly.
async function googleItem(u, title, env) {
  const host = u.hostname.replace(/^www\./, '').toLowerCase(), label = host.split('.')[0].replace(/[^a-z0-9]/g, '');
  const gl = String(env.SERPER_COUNTRY || 'au').toLowerCase(), out = {};
  const words = t => new Set(String(t || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 2));
  const want = words(title), alike = t => { const w = words(t); let n = 0; want.forEach(x => { if (w.has(x)) n++; }); return want.size ? n / want.size : 0; };
  try {
    const d = await get('https://google.serper.dev/shopping', { method: 'POST', headers: { 'x-api-key': env.SERPER_API_KEY, 'content-type': 'application/json' },
      body: JSON.stringify({ q: title, gl, hl: 'en' }) }, 'json', 1);
    for (const it of d.shopping || []) {
      const same = String(it.link || '').toLowerCase().includes(host) || String(it.source || '').toLowerCase().replace(/[^a-z0-9]/g, '').includes(label);
      if (same && !out.price) { const m = parseMoney(it.price, COUNTRY_CURRENCY[gl] || 'USD'); if (m.price) { out.price = m.price; out.currency = m.currency; } }
      if (!out.image && it.imageUrl && (same || alike(it.title) >= 0.7)) out.image = it.imageUrl;
    }
  } catch (e) { /* no shopping results */ }
  if (!out.image) {
    try {
      const d = await get('https://google.serper.dev/images', { method: 'POST', headers: { 'x-api-key': env.SERPER_API_KEY, 'content-type': 'application/json' },
        body: JSON.stringify({ q: `${title} site:${host}`, gl, hl: 'en' }) }, 'json', 1);
      const im = (d.images || []).find(x => /^https:\/\//.test(x.imageUrl || '') && alike(x.title) >= 0.5) || (d.images || [])[0];
      if (im && /^https?:\/\//.test(im.imageUrl || '')) out.image = im.imageUrl.replace(/^http:/, 'https:');
    } catch (e) { /* no image */ }
  }
  return out;
}
async function apiPrice(url, env = {}) {
  let u;
  try { u = new URL(url.searchParams.get('url') || ''); } catch (e) { return json({ error: 'Not a web address' }, url, 0, 400); }
  const host = u.hostname.toLowerCase();
  if (!/^https?:$/.test(u.protocol) || !goodDomain(host) || /^[\d.]+$/.test(host) || host === url.hostname) return json({ error: 'Not a shop address' }, url, 0, 400);
  const title = shortText(url.searchParams.get('title') || '', 140), useGoogle = url.searchParams.get('g') === '1' && !!env.SERPER_API_KEY && !!title;
  let html = '', out = {}, via = '';
  try { const k = await knownItem(u, env); if (k && (k.price || k.image)) { out = k; via = 'api'; } } catch (e) { /* fall back to the page */ }
  if (!out.price) {
    try { html = await get(u.href, {}, 'text', 1); const pg = pagePrice(html); out = { ...pg, image: out.image || '' }; } catch (e) { out.error = e.message; }
    const handle = (u.pathname.match(/\/products\/([^/?#.]+)/) || [])[1];
    if ((!out.price || !out.was) && handle) { // a Shopify shop: its product .js has the price, the earlier price and stock
      try {
        const pj = await get(`${u.origin}/products/${handle}.js`, {}, 'json', 1);
        if (pj && pj.price != null) {
          const pr = num(pj.price) / 100, cmp = num(pj.compare_at_price) / 100;
          if (!out.price) out.price = pr;
          if (!out.currency) out.currency = (html.match(/"currency"\s*:\s*"([A-Z]{3})"/) || [])[1] || '';
          const was = wasPrice(cmp, out.price); if (was) out.was = was;
          if (pj.available === false) out.soldOut = true;
          if (!out.image && pj.featured_image) out.image = String(pj.featured_image).replace(/^\/\//, 'https://');
          delete out.error;
        }
      } catch (e) { /* not Shopify */ }
    }
    if (out.price && !/^[A-Z]{3}$/.test(out.currency || '')) { // no currency code on the page: the first price sign, or the shop's country
      const sym = (html.match(/(?:A\$|AU\$|US\$|NZ\$|C\$|£|€|¥)\s?\d/) || [''])[0];
      out.currency = (sym && parseMoney(sym.replace(/\d$/, '') + '1', 'USD').currency) || (/\.au$/.test(host) ? 'AUD' : 'USD');
    }
    if (!out.image) {
      const img = (html.match(/<meta[^>]+property=["']og:image(?::secure_url)?["'][^>]*content=["']([^"']+)/i) || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]*property=["']og:image["']/i) || [])[1];
      out.image = img && /^https?:\/\//.test(img) ? img.replace(/&amp;/g, '&').replace(/^http:/, 'https:') : img && img.startsWith('//') ? 'https:' + img : '';
    }
  }
  if ((!out.price || !out.image) && useGoogle) {
    const g = await googleItem(u, title, env);
    if (!out.price && g.price) { out.price = g.price; out.currency = g.currency; }
    if (!out.image && g.image) out.image = g.image;
    via = via || 'google';
  }
  const body = { price: out.price || 0, currency: out.currency || '', ...(out.was ? { was: out.was } : {}), ...(out.soldOut ? { soldOut: true } : {}), ...(out.image ? { image: out.image } : {}), ...(via ? { via } : {}) };
  if (!out.price && !out.image) body.error = out.error || 'No price on the page';
  return json(body, url, out.price || out.image ? 21600 : 3600);
}

// ---------- WooCommerce shops (small shops on WordPress) ----------
async function wooStore(term, page, env, domain) {
  if (!goodDomain(domain || '')) throw new Error('Not a shop address');
  const p = pageNum(page, MAX_PAGE);
  let d;
  try { d = await get(`https://${domain}/wp-json/wc/store/v1/products?search=${enc(term)}&per_page=50&page=${p}`, {}, 'json'); }
  catch (e) { throw new Error(/HTTP|Blocked|Timed/.test(e.message) ? e.message : 'Not a WooCommerce shop, or it blocks searches'); }
  if (!Array.isArray(d)) throw new Error('Not a WooCommerce shop');
  const listings = d.map(it => {
    const pr = it.prices || {}, unit = 10 ** (parseInt(pr.currency_minor_unit, 10) || 0);
    const price = num(pr.price) / unit, regular = num(pr.regular_price) / unit, img = (it.images || [])[0] || {};
    return {
      id: String(it.id), url: it.permalink || `https://${domain}/?p=${it.id}`, title: strip(it.name || ''),
      price, currency: pr.currency_code || 'USD', was: wasPrice(regular, price), image: img.thumbnail || img.src || '',
      extra: { shop: domain, soldOut: it.is_in_stock === false || undefined },
    };
  }).filter(l => l.title);
  return { listings, next: d.length >= 50 && p < MAX_PAGE ? p + 1 : null };
}

// ---------- Google Lens (optional, paid): finds the item in your photo anywhere on the web ----------
// Needs a SERPAPI_KEY secret and a KV namespace bound as PHOTOS: Lens fetches the photo from a link,
// so the Worker keeps it for 10 minutes at /api/photo/<id>.jpg and then it expires by itself.
const lensUse = new Map();
const SOCIAL = /(^|\.)(instagram|facebook|pinterest|tiktok|youtube|x|twitter|reddit|tumblr|threads|weibo|xiaohongshu|lemon8)\./i;
async function apiLens(request, url, env) {
  const fail = (error, status = 200) => json({ listings: [], error }, url, 0, status);
  if (!env.SERPAPI_KEY || !env.PHOTOS) return fail('Google Lens needs a SERPAPI_KEY secret and PHOTOS storage on the Worker.', 403);
  const origin = request.headers.get('origin');
  if (origin && origin !== url.origin) return fail('Not allowed from another site', 403);
  const day = new Date().toISOString().slice(0, 10), who = day + ':' + (request.headers.get('cf-connecting-ip') || 'anon');
  const limit = Math.max(0, parseInt(env.LENS_DAILY_LIMIT || '20', 10) || 0), used = lensUse.get(who) || 0;
  if (used >= limit) return fail(`Daily limit of ${limit} Google Lens searches reached.`, 429);
  let body;
  try { body = JSON.parse(await request.text()); } catch (e) { return fail('Bad request', 400); }
  const b64 = jpeg(body.photo);
  if (!b64) return fail('No photo', 400);
  lensUse.set(who, used + 1);
  const id = crypto.randomUUID();
  const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
  await env.PHOTOS.put(id, bytes, { expirationTtl: 600 });
  const photoUrl = `${url.origin}/api/photo/${id}.jpg`;
  let d;
  try { d = await get(`https://serpapi.com/search.json?engine=google_lens&url=${enc(photoUrl)}&country=${enc(String(env.SERPER_COUNTRY || 'au').toLowerCase())}&hl=en&api_key=${enc(env.SERPAPI_KEY)}`, {}, 'json', 1); }
  catch (e) { return fail('Google Lens: ' + e.message); }
  if (d.error) return fail('Google Lens: ' + shortText(d.error, 160));
  const listings = (d.visual_matches || []).slice(0, 60).map((m, i) => {
    const pr = m.price || {}, money = parseMoney(String(pr.value || ''), 'USD');
    if (pr.extracted_value) money.price = num(pr.extracted_value);
    return { id: String(m.link || i), url: m.link, title: strip(m.title || ''), price: money.price || 0, currency: money.currency || 'USD', image: m.thumbnail || m.image || '', extra: { shop: m.source || domainOf(m.link) } };
  }).filter(l => /^https?:\/\//.test(l.url || '') && l.title && !SOCIAL.test(domainOf(l.url) + '.'));
  return json({ listings, left: limit - used - 1 }, url, 0);
}
async function apiPhoto(url, env) {
  const id = url.pathname.slice('/api/photo/'.length).replace(/\.jpg$/, '');
  if (!env.PHOTOS || !/^[0-9a-f-]{36}$/.test(id)) return new Response('Not found', { status: 404 });
  const data = await env.PHOTOS.get(id, 'arrayBuffer');
  return data ? new Response(data, { headers: { 'content-type': 'image/jpeg', 'cache-control': 'no-store' } }) : new Response('Gone', { status: 404 });
}

// ---------- Shopify shops (brand stores and boutiques, e.g. roa-hiking.com, kith.com) ----------
// Every Shopify shop answers /search/suggest.json, so any of them can be added in Settings.
const shopCurrency = {};

async function shopifyStore(term, page, env, domain) {
  if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(domain || '')) throw new Error('Not a shop address');
  const base = 'https://' + domain;
  let d;
  try {
    [d] = await Promise.all([
      get(`${base}/search/suggest.json?q=${enc(term)}&resources[type]=product&resources[limit]=10`, {}, 'json'),
      shopCurrency[domain] ? null : get(`${base}/cart.js`, {}, 'json', 1).then(c => { shopCurrency[domain] = c.currency; }).catch(() => {}),
    ]);
  } catch (e) {
    throw new Error(/HTTP|Blocked|Timed/.test(e.message) ? e.message : 'Not a Shopify shop, or it blocks searches');
  }
  const products = (((d || {}).resources || {}).results || {}).products || [];
  const listings = products.map(p => ({
    id: String(p.id || p.handle),
    url: base + String(p.url || '/products/' + p.handle).split('?')[0],
    title: strip(p.title),
    price: num(p.price),
    was: wasPrice(num(p.compare_at_price_max || p.compare_at_price_min || p.compare_at_price), num(p.price)),
    currency: shopCurrency[domain] || 'USD',
    image: (p.featured_image && p.featured_image.url) || p.image || '',
    extra: { brand: p.vendor && /[a-z]/i.test(p.vendor) ? strip(p.vendor) : undefined, type: p.type || undefined, shop: domain, soldOut: p.available === false || undefined },
  }));
  return { listings, next: null };
}
